152: function pointToMap(clientX, clientY) {
153:   const r = canvas.getBoundingClientRect();
154:   const px = clientX - r.left;
155:   const py = clientY - r.top;
156:   return {
157:     px, py,
158:     nx: px / Math.max(1, r.width),
159:     ny: py / Math.max(1, r.height),
160:     inside: px >= 0 && py >= 0 && px <= r.width && py <= r.height,
161:   };
162: }
