164: let toastTimer = 0;
165: function toast(message, type = '') {
166:   const wrap = $('#toasts');
167:   const key = message + type;
168:   const now = performance.now();
169:   const existing = [...wrap.children].find(el => el.dataset.key === key);
170:   if (existing && now - toastTimer < 500) return;
171:   toastTimer = now;
172:   const el = document.createElement('div');
173:   el.className = `toast ${type}`;
174:   el.dataset.key = key;
175:   el.textContent = message;
176:   wrap.appendChild(el);
177:   while (wrap.children.length > 3) wrap.removeChild(wrap.firstChild);
178:   setTimeout(() => {
179:     el.classList.add('out');
180:     setTimeout(() => el.remove(), 320);
181:   }, 2600);
182: }
