225: function onCardDown(e, type, card) {
226:   if (e.button !== undefined && e.button !== 0) return;
227:   if (!game.started) return;
228:   if (game.phase === 'victory' || game.phase === 'defeat') return;
229:   e.preventDefault();
230:   audio.ensure();
231:   const def = TOWERS[type];
232:   if (game.credits < def.cost) {
233:     audio.error();
234:     toast(`Need ${def.cost - game.credits} more credits for ${def.short}`, 'bad');
235:     return;
236:   }
237:   drag = {
238:     type,
239:     card,
240:     startX: e.clientX,
241:     startY: e.clientY,
242:     moved: false,
243:     pointerId: e.pointerId,
244:     captured: false,
245:   };
246:   try {
247:     card.setPointerCapture(e.pointerId);
248:     drag.captured = true;
249:   } catch {}
250: }
251: 
252: window.addEventListener('pointermove', (e) => {
253:   if (!drag) return;
254:   if (!drag.moved) {
255:     const dx = e.clientX - drag.startX;
256:     const dy = e.clientY - drag.startY;
257:     if (Math.hypot(dx, dy) < 7) return;
258:     drag.moved = true;
259:     audio.ensure();
260:     // close inspector + arm the tower
261:     closeInspector(true);
262:     if (selectedType) cancelPlacement(true);
263:     selectedType = drag.type;
264:     game.setPending(drag.type);
265:     setArmed(drag.type);
266:     drag.card.classList.add('dragging');
267:     dragGhost.innerHTML = `
268:       <span class="tower-icon">${TOWERS[drag.type].icon}</span>
269:       <span class="ghost-name">${TOWERS[drag.type].short}</span>
270:       <span class="ghost-cost">${COIN}${TOWERS[drag.type].cost}</span>`;
271:     dragGhost.classList.remove('hidden');
272:     dragGhost.classList.remove('bad');
273:     ghostVisible = true;
274:     audio.ui();
275:   }
276:   if (!drag.moved) return;
277:   dragGhost.style.left = `${e.clientX}px`;
278:   dragGhost.style.top = `${e.clientY}px`;
279:   const pos = pointToMap(e.clientX, e.clientY);
280:   if (pos.inside) {
281:     game.setPreview(pos.nx, pos.ny);
282:     const valid = game.preview?.valid ?? false;
283:     dragGhost.classList.toggle('bad', !valid);
284:     placeHint.classList.add('hidden');
285:   } else {
286:     game.setPreview(null);
287:     dragGhost.classList.remove('bad');
288:   }
289: });
290: 
291: window.addEventListener('pointerup', (e) => {
292:   if (!drag) return;
293:   const d = drag;
294:   drag = null;
295:   try { if (d.captured && d.card.hasPointerCapture(d.pointerId)) d.card.releasePointerCapture(d.pointerId); } catch {}
296:   d.card.classList.remove('dragging');
297:   dragGhost.classList.add('hidden');
298:   ghostVisible = false;
299: 
300:   if (!d.moved) {
301:     // tap on the card → arm placement for the next map tap
302:     if (selectedType === d.type) {
303:       cancelPlacement();
304:     } else {
305:       closeInspector(true);
306:       game.setPending(d.type);
307:       selectedType = d.type;
308:       setArmed(d.type);
309:       audio.ui();
310:       toast(`Tap the sand to deploy ${TOWERS[d.type].short}`);
311:     }
312:     return;
313:   }
314: 
315:   const pos = pointToMap(e.clientX, e.clientY);
316:   let placed = false;
317:   let reason = '';
318:   if (pos.inside) {
319:     const res = game.placeTower(d.type, pos.nx, pos.ny);
320:     placed = res.ok;
321:     reason = res.reason;
322:   }
323:   game.setPending(null);
324:   game.setPreview(null);
325:   selectedType = null;
326:   setArmed(null);
327:   if (placed) {
328:     toast(`${TOWERS[d.type].name} deployed`, 'good');
329:   } else if (pos.inside && reason) {
330:     audio.error();
331:     toast(reason, 'bad');
332:   }
333:   syncUI(true);
334: });
