421: function refreshInspector() {
422:   const t = game.selected;
423:   if (!t) { closeInspector(true); return; }
424:   const def = TOWERS[t.type];
425:   const lv = towerLevel(t.type, t.level);
426:   $('#inspectIcon').innerHTML = def.icon;
427:   $('#inspectName').textContent = def.name;
428:   $('#inspectLevel').textContent = `LEVEL ${t.level} / 4  ·  ${def.role}`;
429:   $('#inspectDesc').textContent = def.desc;
430:   $('#statDamage').textContent = lv.damage % 1 === 0 ? lv.damage : lv.damage.toFixed(1);
431:   $('#statRange').textContent = Math.round(lv.range);
432:   $('#statRate').textContent = `${(1 / lv.cooldown).toFixed(1)}/s`;
433:   const mode = TARGET_MODES.find(m => m.id === t.mode) || TARGET_MODES[0];
434:   $('#targetMode').textContent = mode.label;
435:   $('#targetBtn').title = `Priority: ${mode.desc}. Tap to change.`;
436:   const up = $('#upgradeBtn');
437:   if (lv.nextLevel) {
438:     up.classList.remove('maxed');
439:     up.classList.toggle('disabled', game.credits < lv.upgrade);
440:     up.querySelector('.up-label').textContent = `UPGRADE TO LEVEL ${lv.nextLevel}`;
441:     up.querySelector('.up-cost').innerHTML = `${COIN}<b id="upgradeCost">${fmt(lv.upgrade)}</b>`;
442:     $('#upgradeDelta').textContent = lv.note;
443:     up.title = `Upgrade for ${lv.upgrade} credits: ${lv.note}`;
444:   } else {
445:     up.classList.add('maxed');
446:     up.classList.remove('disabled');
447:     up.querySelector('.up-label').textContent = 'ELITE TIER REACHED';
448:     up.querySelector('.up-cost').innerHTML = '<b>MAX</b>';
449:     $('#upgradeDelta').textContent = 'This tower is fully upgraded';
450:     up.title = 'Fully upgraded';
451:   }
452:   $('#sellValue').textContent = fmt(sellValue(t));
453: }
