496: let lastHud = { credits: -1, lives: -1, wave: -1, started: false, map: '' };
497: let lastIntelKey = '';
498: 
499: function syncIntel(h) {
500:   const activeMap = game.started ? game.map : selectedMap;
501:   const key = `${activeMap.id}:${game.started}:${h.wave}:${h.phase}`;
502:   if (key === lastIntelKey) return;
503:   lastIntelKey = key;
504:   const body = $('#intelBody');
505:   const threat = $('#intelThreat');
506:   const title = $('#intelTitle');
507:   if (!body) return;
508:   if (!game.started) {
509:     body.innerHTML = '<span class="intel-tip">Deploy the outpost to see enemy movements.</span>';
510:     threat.textContent = 'STANDBY';
511:     threat.className = 'threat';
512:     return;
513:   }
514:   if (h.phase === 'victory' || h.phase === 'defeat') {
515:     body.innerHTML = '<span class="intel-tip">Mission concluded. Redeploy for another run.</span>';
516:     threat.textContent = h.phase === 'victory' ? 'SECURED' : 'OFFLINE';
517:     threat.className = 'threat';
518:     return;
519:   }
520:   title.textContent = h.phase === 'wave' ? 'WAVE INTEL' : 'NEXT WAVE INTEL';
521:   const specs = makeWave(h.wave, activeMap.id);
522:   const counts = {};
523:   for (const s of specs) counts[s.type] = (counts[s.type] || 0) + 1;
524:   const roster = waveRoster(h.wave, activeMap.id);
525:   const order = [...new Set([roster.line, roster.fast, roster.heavy, roster.boss])];
526:   body.innerHTML = order
527:     .filter(t => counts[t])
528:     .map((t) => {
529:       const def = ENEMY_TYPES[t];
530:       return `<span class="intel-chip"><i class="enemy-dot ${def.boss ? 'boss' : ''}" style="--dotc:${def.color}"></i><b>${counts[t]}</b>${def.short}</span>`;
531:     })
532:     .join('');
533:   let level = 'LOW';
534:   const bossEvery = activeMap.bossEvery ?? 10;
535:   const bossWave = (bossEvery > 0 && h.wave % bossEvery === 0) || h.wave === activeMap.waves;
536:   if (h.wave > 18 || bossWave) level = 'EXTREME';
537:   else if (h.wave > 11) level = 'HIGH';
538:   else if (h.wave > 4) level = 'MODERATE';
539:   threat.textContent = `${level} THREAT`;
540:   threat.className = `threat ${level === 'MODERATE' ? 'moderate' : level === 'HIGH' ? 'high' : level === 'EXTREME' ? 'extreme' : ''}`;
541: }
