/* compact desktop / phone-landscape mode: keep all six cards on the page */
@media (max-height: 560px) {
  .map-screen { --map-card-w: clamp(140px, min(25vw, calc((100vh - 190px) * 8 / 9)), 280px); }
  .map-screen .menu-topbar,
  .map-screen .map-page-head { display: none; }
  .map-shell { padding-top: 4px; padding-bottom: 4px; gap: 4px; }
  .map-stage { padding: 0 38px; }
  .map-arrow { width: 32px; height: 44px; }
  .map-shell .dock-btn svg { width: 34px; height: 34px; padding: 7px; }
  .map-shell .dock-btn b { font-size: 6px; }
  .map-pagebar { min-height: 10px; }
}

/* portrait tablets: still exactly six slots, two across and three down */
@media (max-width: 900px) and (min-width: 541px) and (orientation: portrait) {
  .map-screen { --map-card-w: clamp(170px, 38vw, 310px); }
  .map-grid {
    grid-template-columns: repeat(2, var(--map-card-w));
    grid-template-rows: repeat(3, auto);
  }
}

/* narrow fallback: six slots in a 2x3 page */
@media (max-width: 540px) {
  .map-screen { --map-card-w: clamp(112px, calc((100vw - 54px) / 2), 230px); }
  .map-stage { padding: 0 6px; }
  .map-arrow { display: none; }
  .map-grid {
    grid-template-columns: repeat(2, var(--map-card-w));
    grid-template-rows: repeat(3, auto);
  }
  .map-tile { border-width: 4px; border-radius: 14px; }
  .map-pagecount { font-size: 5px; }
}

